style:
/* 简牍 —— 棕色双线 + 衬线字 + 左栏模块标题 */

.tw-cosolar--jiandu.resume-paper {
  background: #fdfaf4;
  color: #2f2a25;
}

/* 页眉：上细线下双线，姓名与职位都用衬线 */
.tw-cosolar--jiandu.resume-paper .paper-header {
  margin-bottom: 4mm;
  padding: 3mm 0 4.2mm;
  border-top: 1px solid #d8c7b0;
  border-bottom: 3px double #c9b79f;
}

.tw-cosolar--jiandu.resume-paper .paper-header--photo {
  align-items: center;
  gap: 8mm;
}

.tw-cosolar--jiandu.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-cosolar--jiandu.resume-paper .paper-name-row {
  gap: 3mm;
}

.tw-cosolar--jiandu.resume-paper .paper-name {
  color: #2b2622;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 2.55);
  font-weight: 600;
  letter-spacing: 0.08em;
  line-height: 1.2;
}

.tw-cosolar--jiandu.resume-paper .paper-identity {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #7d6f60;
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-cosolar--jiandu.resume-paper .paper-role {
  margin-top: 1.8mm;
  color: #8f6a45;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 1.08);
  font-weight: 600;
  letter-spacing: 0.06em;
}

.tw-cosolar--jiandu.resume-paper .paper-contacts--labeled {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-top: 4.2mm;
  padding: 0;
  border: none;
  color: #4a423a;
  font-size: calc(var(--paper-base-size) * 0.87);
}

.tw-cosolar--jiandu.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
  min-width: 0;
}

.tw-cosolar--jiandu.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--jiandu.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #8a7a68;
}

.tw-cosolar--jiandu.resume-paper .paper-photo {
  order: 2;
  width: 24mm;
  height: 32mm;
  border: 0.4mm solid #d8c7b0;
  border-radius: 0;
  object-fit: cover;
  box-shadow: none;
}

/* 每个模块：左栏标题、右栏正文，模块之间发丝线分隔 */
.tw-cosolar--jiandu.resume-paper .paper-section {
  display: grid;
  grid-template-columns: 25mm minmax(0, 1fr);
  column-gap: 6mm;
  margin-bottom: 0;
  padding: 4mm 0 4.6mm;
  border-top: 1px solid #ddd0bd;
}

.tw-cosolar--jiandu.resume-paper .paper-content > .paper-section:first-child {
  border-top: none;
  padding-top: 1.6mm;
}

.tw-cosolar--jiandu.resume-paper .paper-style-line .paper-section__title {
  display: block;
  margin: 0;
  padding: 0;
  border: none;
  color: #8f6a45;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 1.06);
  font-weight: 600;
  letter-spacing: 0.1em;
  line-height: 1.4;
}

.tw-cosolar--jiandu.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-cosolar--jiandu.resume-paper .paper-section__icon {
  display: none;
}

.tw-cosolar--jiandu.resume-paper .paper-section__body {
  min-width: 0;
  color: #3a332c;
}

/* 条目：标题在左、日期在右，专业 / 职位跟一行 */
.tw-cosolar--jiandu.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 4mm;
  row-gap: 0.8mm;
}

.tw-cosolar--jiandu.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-cosolar--jiandu.resume-paper .paper-item > .paper-item-head {
  flex: 1 1 100%;
}

.tw-cosolar--jiandu.resume-paper .paper-item-title {
  color: #2b2622;
  font-weight: 700;
}

.tw-cosolar--jiandu.resume-paper .paper-item-period {
  color: #6f6457;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-cosolar--jiandu.resume-paper .paper-item > .paper-item-sub {
  flex: 1 0 100%;
  margin-top: 0.2mm;
  color: #4a423a;
}

.tw-cosolar--jiandu.resume-paper .paper-item-sub span + span::before {
  content: " | ";
  margin-right: 0;
  color: #c3b6a2;
}

.tw-cosolar--jiandu.resume-paper .paper-item-tag {
  color: #8f6a45;
}

/* 求职意向：右栏一行标签连排 */
.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
}

.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item-head {
  display: flex;
  flex: 0 0 auto;
  gap: 8mm;
  justify-content: flex-start;
}

.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item-title::before {
  content: "意向岗位：";
  color: #8a7a68;
  font-weight: 400;
}

.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item-period::before {
  content: "意向城市：";
  color: #8a7a68;
  font-weight: 400;
}

.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item-sub {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 8mm;
  margin-top: 0;
  color: #3a332c;
}

.tw-cosolar--jiandu.resume-paper .is-job_intention .paper-item-sub span + span::before {
  content: "·";
  margin-right: 6mm;
  color: #c3b6a2;
}

/* 正文细节 */
.tw-cosolar--jiandu.resume-paper .paper-note {
  color: #5f574c;
}

.tw-cosolar--jiandu.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  color: #8f6a45;
  font-weight: 600;
}

.tw-cosolar--jiandu.resume-paper .paper-meta-line {
  color: #7d7263;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-cosolar--jiandu.resume-paper .paper-rich {
  color: #3f382f;
}

.tw-cosolar--jiandu.resume-paper .paper-rich li {
  margin: 0.4mm 0;
}

.tw-cosolar--jiandu.resume-paper .paper-rich li::marker {
  color: #8f6a45;
}

.tw-cosolar--jiandu.resume-paper .paper-skill {
  border-bottom: 1px solid #ebe1d1;
}

.tw-cosolar--jiandu.resume-paper .paper-skill__name {
  color: #2f2a25;
  font-weight: 600;
}

.tw-cosolar--jiandu.resume-paper .paper-skill__dots {
  display: none;
}

.tw-cosolar--jiandu.resume-paper .paper-skill__level {
  display: inline;
  color: #6f6457;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-cosolar--jiandu.resume-paper .paper-footer {
  margin-top: 6mm;
  padding-top: 2.4mm;
  border-top: 1px solid #ddd0bd;
  color: #a29584;
}
